source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Horizontal clue rows encode a repeating sequence down the grid.
    clue_rows = []
    horizontal = True
    for r, row in enumerate(grid):
        nz = [x for x in row if x != 0]
        if nz:
            if len(nz) != w or len(set(nz)) != 1:
                horizontal = False
                break
            clue_rows.append((r, nz[0]))
    if horizontal and clue_rows:
        p = len(clue_rows)
        motif = {}
        for r, color in clue_rows:
            phase = r % p
            if phase in motif and motif[phase] != color:
                horizontal = False
                break
            motif[phase] = color
        if horizontal and len(motif) == p:
            return [[motif[r % p] for _ in range(w)] for r in range(h)]

    # Otherwise, the clues are diagonal samples of a periodic diagonal weave.
    # Find the smallest period for which every phase has one consistent color.
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    for p in range(1, max(h, w) + 1):
        motif = {}
        valid = True
        for r, c, color in cells:
            phase = (c - r) % p
            if phase in motif and motif[phase] != color:
                valid = False
                break
            motif[phase] = color
        if valid and len(motif) == p:
            return [[motif[(c - r) % p] for c in range(w)] for r in range(h)]

    # Fallback: nearest periodic model from the available diagonal clues.
    if cells:
        p = max(h, w)
        motif = {}
        for r, c, color in cells:
            motif[(c-r) % p] = color
        return [[motif.get((c-r) % p, 0) for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
